import SectionHeading from "../components/SectionHeading";
import VerseBox from "../components/VerseBox";
import CardLink from "../components/CardLink";

const resources = [
  { icon: "🤲", name: "Hisn al-Muslim", desc: "Fortress of the Muslim — authentic Duas from Quran and Sunnah for every occasion, with transliteration.", link: "https://hisnulmuslim.com" },
  { icon: "🌅", name: "Morning & Evening Adhkar", desc: "Complete morning and evening supplications from the Sunnah — the daily shield of the believer.", link: "https://sunnah.com/collections" },
  { icon: "🌙", name: "Ramadhan Duas", desc: "Special Duas for Ramadan, Laylatul Qadr, Eid, and the blessed nights of the Islamic year.", link: "https://ramadhanguide.com/duas" },
  { icon: "📿", name: "Daily Duas", desc: "Supplications for eating, sleeping, travelling, entering the home, and all everyday occasions — with audio.", link: "https://dailyduas.com" },
  { icon: "💔", name: "Duas for Hardship", desc: "Prophetic remedies for anxiety, illness, debt, and distress — the believer's toolkit for difficult times.", link: "https://hisnulmuslim.com" },
  { icon: "🕌", name: "Post-Prayer Adhkar", desc: "Authenticated dhikr after the five daily prayers as narrated in Sahih Bukhari, Muslim, and Abu Dawud.", link: "https://sunnah.com/nawawi40" },
];

export default function DuasPage() {
  return (
    <div>
      <div className="page-header">
        <div className="bismillah">وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ</div>
        <h2>Duas & Dhikr</h2>
        <p>"And your Lord says: Call upon Me; I will respond to you." — Quran 40:60</p>
      </div>

      <SectionHeading title="Featured Duas" tag="Authentic Supplications" />
      <VerseBox arabic="رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ" translation='"Our Lord, give us in this world that which is good and in the Hereafter that which is good and protect us from the punishment of the Fire."' ref="Surah Al-Baqarah (2:201)" />
      <VerseBox arabic="اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ" translation='"O Allah, I seek refuge in You from anxiety and sorrow, from weakness and laziness, from miserliness and cowardice, from the burden of debts and from being overpowered by men."' ref="Sahih al-Bukhari 6369" />

      <SectionHeading title="Dua Resources" tag="Trusted Sources" />
      <div className="grid">
        {resources.map(r => (
          <div className="card" key={r.name}>
            <div className="card-icon">{r.icon}</div>
            <h4>{r.name}</h4>
            <p>{r.desc}</p>
            <CardLink href={r.link} />
          </div>
        ))}
      </div>
    </div>
  );
}
